import org.junit.jupiter.api.Test;

/**
 * The time limit escalates in three steps: it requests cooperative cancellation when the limit elapses, interrupts
 * threads still inside the iteration after the interrupt grace, and closes the iteration after the close grace.
 */
class TimeLimitIterationLadderTest {

	private static final long HOUR = TimeUnit.HOURS.toMillis(1);
	private static final long SHORT_GRACE = 150;

	@Test
	void acceptedCancellationStopsTheCallWithoutInterruptingIt() throws Exception {
		Source source = new Source();
		source.acceptCancellation = true;
		source.releaseOnCancellation = true;
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Ladder timed = new Ladder(source, 50, HOUR, HOUR);
			Future<Boolean> call = executor.submit(() -> {
				assertSame(timed.timeout, assertThrows(IllegalStateException.class, timed::hasNext));
				return Thread.currentThread().isInterrupted();
			});
			assertFalse(call.get(5, TimeUnit.SECONDS), "an accepted request must not leave an interrupt behind");
			timed.close();
			assertEquals(1, source.cancellationCalls.get());
			assertEquals(0, source.interruptsSeen.get(), "cooperative cancellation must not interrupt the call");
			assertEquals(1, source.closeCalls.get());
			assertFalse(source.closedWhileActive.get());
		}
	}

	@Test
	void ignoredCancellationInterruptsTheActiveCallAfterTheInterruptGrace() throws Exception {
		Source source = new Source();
		source.returnOnInterrupt = true;
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			long started = System.nanoTime();
			Ladder timed = new Ladder(source, 50, SHORT_GRACE, HOUR);
			Future<Boolean> call = executor.submit(() -> {
				assertSame(timed.timeout, assertThrows(IllegalStateException.class, timed::hasNext));
				return Thread.currentThread().isInterrupted();
			});
			assertFalse(call.get(5, TimeUnit.SECONDS),
					"the interrupt delivered by the time limit must be cleared before the timeout is reported");
			long interruptedAfter = TimeUnit.NANOSECONDS.toMillis(source.interruptedAtNanos.get() - started);
			assertTrue(interruptedAfter >= 50 + SHORT_GRACE - 20,
					"interrupt arrived after " + interruptedAfter + " ms");
			assertEquals(1, source.cancellationCalls.get());
			assertEquals(1, source.interruptsSeen.get());
			assertFalse(source.closedWhileActive.get(), "the interrupted call returned before close");
			timed.close();
			assertEquals(1, source.closeCalls.get());
		}
	}

	@Test
	void ignoredInterruptIsFollowedByAForcedCloseAfterTheCloseGrace() throws Exception {
		Source source = new Source();
		source.ignoreInterrupts = true;
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Ladder timed = new Ladder(source, 50, SHORT_GRACE, SHORT_GRACE);
			Future<Boolean> call = executor.submit(() -> {
				assertSame(timed.timeout, assertThrows(IllegalStateException.class, timed::hasNext));
				return Thread.currentThread().isInterrupted();
			});
			assertFalse(call.get(5, TimeUnit.SECONDS), "the forced close must not leave an interrupt behind");
			assertTrue(source.closedWhileActive.get(), "the last step closes beneath the active call");
			assertTrue(source.interruptsSeen.get() >= 1);
			assertNotSame(Thread.currentThread(), source.closeThread.get());
			timed.close();
			assertEquals(1, source.closeCalls.get());
		}
	}

	@Test
	void idleTimeoutClosesOnlyAfterBothGraces() throws Exception {
		Source source = new Source();
		source.acceptCancellation = true;
		long started = System.nanoTime();
		Ladder timed = new Ladder(source, 20, SHORT_GRACE, SHORT_GRACE);
		try {
			assertTrue(source.cancelled.await(5, TimeUnit.SECONDS), "the first step requests cancellation");
			assertTrue(source.closed.await(5, TimeUnit.SECONDS), "the last step closes an idle iteration");
			long closedAfter = TimeUnit.NANOSECONDS.toMillis(source.closedAtNanos.get() - started);
			assertTrue(closedAfter >= 20 + 2 * SHORT_GRACE - 20, "idle close ran after " + closedAfter + " ms");
			assertSame(timed.timeout, assertThrows(IllegalStateException.class, timed::hasNext));
		} finally {
			timed.close();
		}
		assertEquals(1, source.closeCalls.get());
	}

	@Test
	void consumerObservingTheTimeoutStopsTheLadder() throws Exception {
		Source source = new Source();
		source.acceptCancellation = true;
		Ladder timed = new Ladder(source, 20, SHORT_GRACE, SHORT_GRACE);
		try {
			assertTrue(source.cancelled.await(5, TimeUnit.SECONDS));
			assertSame(timed.timeout, assertThrows(IllegalStateException.class, timed::hasNext));
			assertTrue(source.closed.await(5, TimeUnit.SECONDS), "an observed timeout closes the idle source");
		} finally {
			timed.close();
		}
		Thread.sleep(3 * SHORT_GRACE);
		assertEquals(1, source.closeCalls.get(), "later steps must not close again");
	}

	@Test
	void stoppedCallIsNeverInterruptedOnItsReusedThread() throws Exception {
		Source source = new Source();
		source.acceptCancellation = true;
		source.releaseOnCancellation = true;
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Ladder timed = new Ladder(source, 20, SHORT_GRACE, SHORT_GRACE);
			assertThrows(ExecutionException.class, () -> executor.submit(timed::hasNext).get(5, TimeUnit.SECONDS));
			Future<Boolean> laterWork = executor.submit(() -> {
				Thread.sleep(3 * SHORT_GRACE);
				return Thread.currentThread().isInterrupted();
			});
			assertFalse(laterWork.get(5, TimeUnit.SECONDS), "a pooled thread must not be interrupted after return");
			timed.close();
		}
	}

	@Test
	void crossThreadCloseDuringAnActiveCallEscalatesAndReturnsImmediately() throws Exception {
		Source source = new Source();
		source.ignoreInterrupts = true;
		try (ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Ladder timed = new Ladder(source, HOUR, SHORT_GRACE, SHORT_GRACE);
			Future<Boolean> call = executor.submit(timed::hasNext);
			assertTrue(source.entered.await(5, TimeUnit.SECONDS));
			long closeStarted = System.nanoTime();
			timed.close();
			assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - closeStarted) < SHORT_GRACE,
					"close must not wait for the active call");
			assertEquals(1, source.cancellationCalls.get(), "close requests cooperative cancellation first");
			assertEquals(0, source.closeCalls.get(), "close is deferred while the call is active");
			assertTrue(source.closed.await(5, TimeUnit.SECONDS), "an ignored close escalates to a forced close");
			assertTrue(source.interruptsSeen.get() >= 1, "the escalation interrupts before it closes");
			call.get(5, TimeUnit.SECONDS);
			assertEquals(1, source.closeCalls.get());
		}
	}

	@Test
	void nonPositiveTimeLimitTimesOutOnFirstUseWithoutEnteringTheSource() {
		for (long limit : new long[] { 0, -5 }) {
			Source source = new Source();
			source.acceptCancellation = true;
			Ladder timed = new Ladder(source, limit, HOUR, HOUR);
			try {
				assertSame(timed.timeout, assertThrows(IllegalStateException.class, timed::hasNext));
				assertEquals(1, source.entered.getCount(), "an expired time limit must not enter the source");
				assertEquals(1, source.cancellationCalls.get());
			} finally {
				timed.close();
			}
			assertEquals(1, source.closeCalls.get());
		}
	}

	@Test
	void defaultGracesAreTwoSeconds() {
		Source source = new Source();
		TimeLimitIteration<Integer> timed = new TimeLimitIteration<>(source, HOUR) {
			@Override
			protected void throwInterruptedException() {
				throw new IllegalStateException("time limit expired");
			}
		};
		try {
			assertEquals(2000, timed.interruptGraceMillis());
			assertEquals(2000, timed.closeGraceMillis());
		} finally {
			timed.close();
		}
		assertInstanceOf(CooperativeCancellation.class, timed);
	}

	private static final class Ladder extends TimeLimitIteration<Integer> {
		private final IllegalStateException timeout = new IllegalStateException("time limit expired");

		private Ladder(CloseableIteration<Integer> source, long limit, long interruptGrace, long closeGrace) {
			super(source, limit, interruptGrace, closeGrace);
		}

		@Override
		protected void throwInterruptedException() {
			throw timeout;
		}
	}

	/** A source whose hasNext blocks until released by cancellation, interruption or close. */
	private static final class Source implements CloseableIteration<Integer>, CooperativeCancellation {
		private final CountDownLatch entered = new CountDownLatch(1);
		private final CountDownLatch cancelled = new CountDownLatch(1);
		private final CountDownLatch released = new CountDownLatch(1);
		private final CountDownLatch closed = new CountDownLatch(1);
		private final AtomicInteger cancellationCalls = new AtomicInteger();
		private final AtomicInteger closeCalls = new AtomicInteger();
		private final AtomicInteger interruptsSeen = new AtomicInteger();
		private final AtomicBoolean active = new AtomicBoolean();
		private final AtomicBoolean closedWhileActive = new AtomicBoolean();
		private final AtomicLong interruptedAtNanos = new AtomicLong();
		private final AtomicLong closedAtNanos = new AtomicLong();
		private final AtomicReference<Thread> closeThread = new AtomicReference<>();
		private volatile boolean acceptCancellation;
		private volatile boolean releaseOnCancellation;
		private volatile boolean returnOnInterrupt;
		private volatile boolean ignoreInterrupts;

		@Override
		public boolean hasNext() {
			active.set(true);
			entered.countDown();
			try {
				while (true) {
					try {
						if (!released.await(10, TimeUnit.SECONDS)) {
							throw new AssertionError("the time limit never released the source");
						}
						return true;
					} catch (InterruptedException interrupted) {
						interruptsSeen.incrementAndGet();
						interruptedAtNanos.compareAndSet(0, System.nanoTime());
						if (returnOnInterrupt) {
							// Code that cannot propagate InterruptedException restores the flag.
							Thread.currentThread().interrupt();
							return true;
						}
						if (!ignoreInterrupts) {
							throw new AssertionError(interrupted);
						}
					}
				}
			} finally {
				active.set(false);
			}
		}

		@Override
		public Integer next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public boolean requestCancellation() {
			cancellationCalls.incrementAndGet();
			cancelled.countDown();
			if (releaseOnCancellation) {
				released.countDown();
			}
			return acceptCancellation;
		}

		@Override
		public void close() {
			closedWhileActive.compareAndSet(false, active.get());
			closeThread.set(Thread.currentThread());
			closedAtNanos.compareAndSet(0, System.nanoTime());
			closeCalls.incrementAndGet();
			released.countDown();
			closed.countDown();
		}
	}
}
